package br.com.onda;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.MediaStore;import android.widget.*;import android.os.*;import androidx.media3.common.*;import androidx.media3.session.MediaController;import java.io.*;import java.util.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class BatchDeleteTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private final List<Uri> fixtures=new ArrayList<>();private Activity owner;private BatchDeleteActivity batch;private DeleteMediaActivity child;
 private Object get(Object o,String field)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(field);f.setAccessible(true);return f.get(o);}
 private interface Check{boolean ok()throws Exception;}
 private void waitFor(Check check)throws Exception{long end=SystemClock.elapsedRealtime()+25000;while(SystemClock.elapsedRealtime()<end){boolean[] value={false};ins.runOnMainSync(()->{try{value[0]=check.ok();}catch(Exception e){throw new RuntimeException(e);}});if(value[0])return;Thread.sleep(80);}throw new AssertionError("Batch state did not complete");}
 private Uri fixture(boolean video)throws Exception{ContentValues v=new ContentValues();String name="Onda-batch-"+UUID.randomUUID();v.put("_display_name",name+(video?".mp4":".m4a"));v.put("title",name);v.put("mime_type",video?"video/mp4":"audio/mp4");v.put("duration",3000);v.put("relative_path",video?"Movies/OndaTest":"Music/OndaTest");v.put("is_pending",1);Uri uri=c.getContentResolver().insert(video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,v);assertNotNull(uri);fixtures.add(uri);try(InputStream in=ins.getContext().getAssets().open(video?"combined.mp4":"audio.m4a");OutputStream out=c.getContentResolver().openOutputStream(uri)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))>0)out.write(bytes,0,n);}v.clear();v.put("is_pending",0);c.getContentResolver().update(uri,v,null,null);return uri;}
 private boolean exists(Uri uri){try(Cursor q=c.getContentResolver().query(uri,new String[]{"_id"},null,null,null)){return q!=null&&q.moveToFirst();}}
 private MediaItem item(Uri uri){return new MediaItem.Builder().setMediaId(uri.getLastPathSegment()).setUri(uri).setMediaMetadata(new MediaMetadata.Builder().setTitle("Áudio "+uri.getLastPathSegment()).build()).build();}
 private void open(boolean video,List<Uri> uris)throws Exception{
  owner=ins.startActivitySync(new Intent(c,video?VideoActivity.class:MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));if(!video)waitFor(()->get(owner,"player")!=null);else waitFor(()->((List<VideoStore.Item>)get(owner,"videos")).stream().filter(i->uris.contains(i.uri)).count()==uris.size());Instrumentation.ActivityMonitor monitor=ins.addMonitor(BatchDeleteActivity.class.getName(),null,false);
  ins.runOnMainSync(()->{if(video){ArrayList<VideoStore.Item> items=new ArrayList<>();try{List<VideoStore.Item> available=(List<VideoStore.Item>)get(owner,"videos");for(VideoStore.Item row:available)if(uris.contains(row.uri))items.add(row);assertEquals(uris.size(),items.size());BatchDeleteActivity.videos(owner,items);}catch(Exception e){throw new RuntimeException(e);}}else{ArrayList<MediaItem> items=new ArrayList<>();for(Uri uri:uris)items.add(item(uri));try{((MediaController)get(owner,"player")).setMediaItems(items);}catch(Exception e){throw new RuntimeException(e);}BatchDeleteActivity.audio(owner,items);}});
  batch=(BatchDeleteActivity)monitor.waitForActivityWithTimeout(10000);ins.removeMonitor(monitor);assertNotNull(batch);ins.waitForIdleSync();
 }
 private void mark(int... indices)throws Exception{ins.runOnMainSync(()->{try{ListView list=(ListView)get(batch,"list");for(int i:indices){list.setItemChecked(i,true);list.getOnItemClickListener().onItemClick(list,list.getChildAt(i),i,i);}}catch(Exception e){throw new RuntimeException(e);}});}
 private void prepare()throws Exception{ins.runOnMainSync(()->{try{((Button)get(batch,"remove")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->get(batch,"confirmation")!=null&&((AlertDialog)get(batch,"confirmation")).isShowing());}
 private void confirm()throws Exception{ins.runOnMainSync(()->{try{((AlertDialog)get(batch,"confirmation")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});}
 @After public void after(){if(child!=null&&!child.isDestroyed())ins.runOnMainSync(child::finish);if(batch!=null&&!batch.isDestroyed())ins.runOnMainSync(batch::finish);if(owner!=null&&!owner.isDestroyed())ins.runOnMainSync(()->{try{if(owner instanceof MainActivity){MediaController player=(MediaController)get(owner,"player");if(player!=null){player.pause();player.clearMediaItems();}}}catch(Exception ignored){}owner.finish();});for(Uri uri:fixtures)try{c.getContentResolver().delete(uri,null,null);}catch(Exception ignored){}}
 @Test public void audioBatchDeletesTwoMarkedFilesAndKeepsThirdAndQueue()throws Exception{List<Uri> uris=Arrays.asList(fixture(false),fixture(false),fixture(false));open(false,uris);mark(0,1);ins.runOnMainSync(()->{try{assertTrue(((TextView)get(batch,"status")).getText().toString().contains("2 de 3"));}catch(Exception e){throw new RuntimeException(e);}});android.graphics.Bitmap image=ins.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"batch-selection.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}prepare();confirm();waitFor(()->batch.isFinishing());assertFalse(exists(uris.get(0)));assertFalse(exists(uris.get(1)));assertTrue(exists(uris.get(2)));waitFor(()->((MediaController)get(owner,"player")).getMediaItemCount()==1);}
 @Test public void cancelConfirmationPreservesEveryFile()throws Exception{List<Uri> uris=Arrays.asList(fixture(false),fixture(false));open(false,uris);mark(0,1);prepare();ins.runOnMainSync(()->{try{((AlertDialog)get(batch,"confirmation")).getButton(AlertDialog.BUTTON_NEGATIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});for(Uri uri:uris)assertTrue(exists(uri));ins.runOnMainSync(()->{try{((Button)get(batch,"cancel")).performClick();}catch(Exception e){throw new RuntimeException(e);}});}
 @Test public void videoBatchDeletesMarkedFilesOnly()throws Exception{List<Uri> uris=Arrays.asList(fixture(true),fixture(true),fixture(true));open(true,uris);mark(0,1);ArrayList<Uri> chosen=new ArrayList<>();ins.runOnMainSync(()->{try{List<?> rows=(List<?>)get(batch,"entries");for(int i=0;i<2;i++)chosen.add((Uri)get(rows.get(i),"uri"));}catch(Exception e){throw new RuntimeException(e);}});prepare();confirm();waitFor(()->batch.isFinishing());for(Uri uri:uris)assertEquals(!chosen.contains(uri),exists(uri));}
 @Test public void changedFileStopsBatchBeforeAnyDeletion()throws Exception{Uri uri=fixture(false);open(false,Collections.singletonList(uri));mark(0);prepare();ContentValues changed=new ContentValues();changed.put("_display_name","Changed-"+UUID.randomUUID()+".m4a");c.getContentResolver().update(uri,changed,null,null);Instrumentation.ActivityMonitor monitor=ins.addMonitor(DeleteMediaActivity.class.getName(),null,false);confirm();child=(DeleteMediaActivity)monitor.waitForActivityWithTimeout(10000);ins.removeMonitor(monitor);assertNotNull(child);waitFor(()->((TextView)get(child,"details")).getText().toString().contains("mudou"));assertTrue(exists(uri));ins.runOnMainSync(child::finish);waitFor(()->!((Boolean)get(batch,"busy")));assertTrue(exists(uri));}
}
